task.en:
Find the error in each of the following program segments and correct the error:
a) #define SIZE 100;
b) SIZE = 10;
c) Assume int b[10] = { 0 }, i;
for (i = 0; i <= 10; ++i) {
b[i] = 1;
}
d) #include <stdio.h>;
e) Assume int a[2][2] = { { 1, 2 }, { 3, 4 } };
a[1, 1] = 5;
f) #define VALUE = 120

example.code:
#include <iostream>
#include <iomanip>
#include <array>

void modifyValue(double val) {
    val += 100.0;
}

int main() {
    constexpr std::size_t SIZE = 3;

    // Exercise 6.4 demo: nested partial initialization
    int table[SIZE][SIZE] = {
        { 1, 8 },
        { 2, 4, 6 },
        { 5 }
    };

    std::cout << "Table 3x3 elements:\n";
    for (std::size_t r = 0; r < SIZE; ++r) {
        for (std::size_t c = 0; c < SIZE; ++c) {
            std::cout << "table[" << r << "][" << c << "] = " << table[r][c] << "\n";
        }
    }

    // Pass individual element by value
    double fractions[2] = { 3.14, 2.71 };
    modifyValue(fractions[0]);
    std::cout << std::fixed << std::setprecision(2);
    std::cout << "fractions[0] after modifyValue: " << fractions[0] << "\n";

    return 0;
}

#include <iostream>
#include <vector>
#include <utility>

void optimizedBubbleSort(std::vector<int>& arr) {
    std::size_t n = arr.size();
    for (std::size_t pass = 0; pass < n - 1; ++pass) {
        bool swapped = false;
        for (std::size_t i = 0; i < n - 1 - pass; ++i) {
            if (arr[i] > arr[i + 1]) {
                std::swap(arr[i], arr[i + 1]);
                swapped = true;
            }
        }
        if (!swapped) {
            break; // Terminate early
        }
    }
}

int main() {
    // Exercise 6.11 demonstration
    std::vector<int> data = { 64, 34, 25, 12, 22, 11, 90 };
    optimizedBubbleSort(data);

    std::cout << "Sorted array:";
    for (int x : data) {
        std::cout << " " << x;
    }
    std::cout << "\n";

    // Exercise 6.10 demonstration: Commission counter bins
    // Gross sales samples for 4 salespeople
    double sales[] = { 3000.0, 5000.0, 1000.0, 9500.0 };
    int salaryCounters[9] = { 0 };

    for (double s : sales) {
        int salary = static_cast<int>(200.0 + 0.09 * s);
        int bin = (salary - 200) / 100;
        if (bin > 8) bin = 8;
        if (bin >= 0) salaryCounters[bin]++;
    }

    std::cout << "Salaries $400-$499 count: " << salaryCounters[2] << "\n";
    std::cout << "Salaries $1000+ count: " << salaryCounters[8] << "\n";
    return 0;
}
